 import { MeshBasicNodeMaterial, PlaneGeometry, DoubleSide } from 'three/webgpu';
import {
  uv,
  vec2,
  texture,
  color,
  mix,
  smoothstep,
  length,
  mul,
  fract,
  sin,
  dot
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const src = config.atlasRegion?.sourceRect;
  const aspect = src && src[2] > 0 && src[3] > 0 ? src[2] / src[3] : 512 / 320;
  const height = 1.6;
  const width = height * aspect;

  const u = uv();

  const surfaceCol = color(colors.surface);
  const inkCol = color(colors.ink);
  const paperCol = color(colors.paper);
  const accentCol = color(colors.accent);

  const gradT = smoothstep(0.0, 1.0, u.y);
  const gradient = mix(surfaceCol, inkCol, gradT);

  const noise = fract(sin(dot(u, vec2(12.9898, 78.233))).mul(43758.5453));
  const grain = mix(gradient, paperCol, noise.mul(0.04));

  const cornerDist = length(vec2(1, 1).sub(u));
  const accentMask = smoothstep(0.65, 0.0, cornerDist);
  const baseColor = mix(grain, accentCol, accentMask.mul(0.08));

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    depthWrite: false
  });

  material.colorNode = baseColor;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = ctx.THREE.SRGBColorSpace;
      const samp = texture(tex);
      material.colorNode = mix(baseColor, samp.rgb, samp.a);
      material.needsUpdate = true;
    });
  }

  const plane = new ctx.THREE.Mesh(geometry, material);
  group.add(plane);

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return group;
}
